const initial={employees:[{id:'e1',name:'نورة',role:'محلل بيانات',department:'التحليلات والجودة',status:'REPORTING'},{id:'e2',name:'عمر',role:'مدير التسويق',department:'التسويق والنمو',status:'WORKING'},{id:'e3',name:'لين',role:'مصمم جرافيك',department:'التصميم والإبداع',status:'WORKING'},{id:'e4',name:'فهد',role:'صانع محتوى',department:'المحتوى والإبداع',status:'RESEARCHING'},{id:'e5',name:'سارة',role:'مدير مشروع',department:'إدارة المشاريع',status:'WAITING_APPROVAL'}],tasks:[{id:'t1',employee:'e2',title:'تحليل جمهور قدّها',project:'قدّها',progress:45},{id:'t2',employee:'e1',title:'تقرير أداء قدّها',project:'قدّها',progress:64}],activities:['عمر بدأ تحليل جمهور قدّها','نورة تجمع بيانات تقرير الأداء','قرار جديد يحتاج موافقة نواف'],decisions:[{title:'اعتماد حملة تسويقية جديدة',detail:'حملة قدّها · انطلاقة أقوى.'},{title:'الموافقة على الهوية البصرية',detail:'شعار وهوية قدّها الجديدة'}],projects:[{name:'مُعِين',status:'قيد المراجعة',progress:76},{name:'قدّها',status:'جاري العمل',progress:61}]};
let state=JSON.parse(localStorage.getItem('nawaf-hq-state')||'null')||initial;let selected=null;const save=()=>localStorage.setItem('nawaf-hq-state',JSON.stringify(state));
function el(s){return document.querySelector(s)}function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function time(){return new Date().toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'})}
function render(){const active=state.employees.filter(x=>x.status!=='IDLE').length;el('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">قدّها<small>QADHA</small></div><div class="brand-copy">أفكار أكبر من الحدود</div><nav class="nav"><button class="active">⌂ الرئيسية</button><button>♙ موظفي AI</button><button>▣ المشاريع</button><button>◈ التسويق</button><button>▤ المحتوى</button><button>▥ التحليلات</button><button>♧ الاجتماعات</button><button>⌾ المعرفة</button><button>⚙ الإعدادات</button></nav><div class="tip">كل فكرة عظيمة<br>تبدأ بقرار بسيط.</div></aside><main class="main"><header class="topbar"><div class="ceo"><div class="avatar">N</div><span>نواف<small>الرئيس التنفيذي</small></span>　☀　♧</div><input class="search" placeholder="ابحث عن أي شيء..." /></header><section class="greeting"><div><h1>👋 صباح الخير يا نواف</h1><p>شركتك تعمل الآن. إليك أهم المستجدات:</p></div><div class="quote">“الأحلام لا تعمل من تلقاء نفسها... لكن فريقك يفعل.”</div></section><section class="kpis"><div class="kpi card"><b>${active}</b><span>موظفين يعملون الآن</span><em>+2 اليوم</em></div><div class="kpi card"><b>${state.tasks.filter(t=>t.progress===100).length+3}</b><span>مهام اكتملت</span><em>+3 اليوم</em></div><div class="kpi card"><b>${state.tasks.length+3}</b><span>مهام قيد التنفيذ</span><em>↗ نشطة الآن</em></div><div class="kpi card"><b>${state.decisions.length}</b><span>قرارات بانتظارك</span><em style="color:#ffbd57">مراجعة مطلوبة</em></div><div class="kpi card"><b>87%</b><span>معدل الإنتاجية</span><em>↗ +5% هذا الأسبوع</em></div></section><section class="grid"><div><div class="office card"><div class="section-title"><span>مكتب قدّها <span class="status"><i class="dot"></i> مباشر الآن</span></span><span class="status">عرض كامل ⛶</span></div><img src="assets/ai-office.png" alt="مكتب الشركة الذكي"/><button class="room r1" data-dept="إدارة المشاريع">إدارة المشاريع <i class="dot"></i></button><button class="room r2" data-dept="التصميم والإبداع">المحتوى والإبداع <i class="dot"></i></button><button class="room r3" data-dept="التسويق والنمو">التسويق <i class="dot"></i></button><button class="room r4" data-dept="الأعمال والمالية">المبيعات <i class="dot"></i></button><button class="room r5" data-dept="التحليلات والجودة">التحليلات <i class="dot"></i></button><button class="room r6" data-dept="التقنية والتطوير">التطوير والأنظمة <i class="dot"></i></button></div><section class="lower"><div class="employees card"><h2>موظفيني AI <span class="status" id="addEmp">+ إضافة موظف</span></h2><div class="employee-row">${state.employees.map(e=>`<article class="employee" data-id="${e.id}"><div class="bot">🤖</div><b>${esc(e.name)}</b><small>${esc(e.role)}</small><small class="live">● ${e.status==='WAITING_APPROVAL'?'ينتظر الموافقة':'يعمل الآن'}</small></article>`).join('')}</div></div><div class="projects card"><h2>المشاريع الحديثة</h2>${state.projects.map(p=>`<div class="project"><span><b>${p.name}</b><small class="status">${p.status}</small></span><span><small>${p.progress}%</small><div class="bar"><i style="width:${p.progress}%"></i></div></span></div>`).join('')}</div><div class="metrics card"><h2>أداء الشركة</h2><div class="metric-grid"><div class="metric"><b>+32%</b><small>المبيعات</small></div><div class="metric"><b>+42%</b><small>العملاء المحتملين</small></div><div class="metric"><b>+68%</b><small>التفاعل</small></div><div class="metric"><b>+125%</b><small>الوصول</small></div></div></div></section></div><aside class="side-stack"><section class="side-card card"><h2>قرارات بانتظارك (${state.decisions.length})</h2>${state.decisions.map((d,i)=>`<div class="approval"><strong>${d.title}</strong><p>${d.detail}</p><div class="buttons"><button class="ok" data-approve="${i}">✓ اعتماد</button><button>تعديل</button><button>رفض</button></div></div>`).join('')}</section><section class="side-card card"><h2>النشاطات الأخيرة <span class="status">عرض الكل</span></h2><div class="feed">${state.activities.slice(0,6).map((a,i)=>`<div><time>${i?'10:'+(24-i*3):time()}</time><span>● ${a}</span></div>`).join('')}</div></section><section class="side-card card"><h2>خطوتك التالية</h2><p style="color:var(--muted)">لديك فرصة رائعة لإحداث فرق أكبر.</p><button class="primary" id="simulate">حرّك الشركة الآن ←</button></section></aside></section></main></div><div class="modal" id="modal"><form class="dialog" id="employeeForm"><h2 id="modalTitle">ملف الموظف</h2><label>الاسم</label><input name="name" required><label>الدور</label><input name="role" required><label>القسم</label><input name="department" required><label>الحالة</label><select name="status"><option>WORKING</option><option>RESEARCHING</option><option>REPORTING</option><option>WAITING_APPROVAL</option><option>IDLE</option></select><label>التعليمات والمسؤوليات</label><textarea name="instructions" placeholder="أضف مسؤوليات الموظف وتعليماته"></textarea><div class="actions"><button type="button" id="close">إلغاء</button><button class="primary">حفظ التغييرات</button></div></form></div><div class="toast" id="toast"></div>`;bind()}
function bind(){document.querySelectorAll('.employee').forEach(x=>x.onclick=()=>openEmployee(x.dataset.id));el('#addEmp').onclick=()=>openEmployee();el('#close').onclick=()=>el('#modal').classList.remove('open');el('#employeeForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f);if(selected){Object.assign(state.employees.find(x=>x.id===selected),o)}else state.employees.push({id:'e'+Date.now(),...o});save();el('#modal').classList.remove('open');toast('تم حفظ ملف الموظف وتحديثه في كل الشركة');render()};document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>{let d=state.decisions.splice(+b.dataset.approve,1)[0];state.activities.unshift(`نواف اعتمد: ${d.title}`);save();toast('تم اعتماد القرار وإشعار الفريق');render()});document.querySelectorAll('.room').forEach(b=>b.onclick=()=>toast(`تم فتح مساحة ${b.dataset.dept}`));el('#simulate').onclick=simulate}
function openEmployee(id){selected=id;const e=state.employees.find(x=>x.id===id)||{name:'',role:'',department:'إدارة المشاريع',status:'WORKING',instructions:''};el('#modalTitle').textContent=id?'تعديل موظف AI':'إضافة موظف AI';Object.entries(e).forEach(([k,v])=>{let input=el(`[name="${k}"]`);if(input)input.value=v});el('#modal').classList.add('open')}
function simulate(){let t=state.tasks.find(x=>x.progress<100);if(!t){toast('كل المهام الحالية مكتملة. أضف مهمة جديدة لاحقًا.');return}t.progress=Math.min(100,t.progress+18);let e=state.employees.find(x=>x.id===t.employee);e.status=t.progress===100?'REPORTING':'WORKING';state.activities.unshift(`${e.name} حدّث ${t.title} إلى ${t.progress}%`);if(t.progress===100)state.activities.unshift(`${e.name} أكمل المهمة وأرسل تقريرًا للمراجعة`);save();toast(`تقدم ${t.title}: ${t.progress}%`);render()}
function toast(x){setTimeout(()=>{const t=el('#toast');if(t){t.textContent=x;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}},20)}render();
